result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "gs1_check.py", "content": """"GS1-style check digit library for medication package codes (educational).

Algorithm for an N-digit payload (N in {7, 11, 12, 13}):
  - Starting from the RIGHTMOST payload digit and moving leftward,
    alternate weights 3, 1, 3, 1, ...
  - check_digit = (10 - (weighted_sum mod 10)) mod 10
  - The full code is payload + check digit (length N+1).
"""

VALID_PAYLOAD_LENGTHS = {7, 11, 12, 13}


def _validate_payload_shape(payload: str) -> str:
    if not isinstance(payload, str):
        raise TypeError("payload must be a string of digits")
    if not payload.isdigit():
        raise ValueError(f"non-digit input: {payload!r}")
    if len(payload) not in VALID_PAYLOAD_LENGTHS:
        raise ValueError(
            f"wrong length {len(payload)}; payload must have "
            f"{sorted(VALID_PAYLOAD_LENGTHS)} digits"
        )
    return payload


def weighted_sum(payload: str) -> int:
    """Return the GS1 weighted sum of the payload digits."""
    payload = _validate_payload_shape(payload)
    total = 0
    weight = 3
    # iterate from the rightmost payload digit leftward
    for ch in reversed(payload):
        total += int(ch) * weight
        weight = 1 if weight == 3 else 3
    return total


def compute(payload: str) -> int:
    """Compute the GS1-style check digit (0-9) for a numeric payload string."""
    s = weighted_sum(payload)
    return (10 - (s % 10)) % 10


def validate(full_code: str) -> bool:
    """Validate a full code (payload + appended check digit)."""
    if not isinstance(full_code, str):
        raise TypeError("full_code must be a string of digits")
    if not full_code.isdigit():
        raise ValueError(f"non-digit input: {full_code!r}")
    if len(full_code) not in {n + 1 for n in VALID_PAYLOAD_LENGTHS}:
        raise ValueError(
            f"wrong length {len(full_code)}; full code must have "
            f"{sorted(n + 1 for n in VALID_PAYLOAD_LENGTHS)} digits"
        )
    payload, check = full_code[:-1], int(full_code[-1])
    return compute(payload) == check


def batch(lines) -> None:
    """Read one code per line and print OK/BAD for each.

    Lines that are malformed (wrong length or non-digit) print BAD.
    """
    for raw in lines:
        code = raw.strip()
        if not code:
            continue  # skip blank lines
        try:
            print("OK" if validate(code) else "BAD")
        except ValueError:
            print("BAD")


if __name__ == "__main__":
    import sys

    batch(sys.stdin)
"})
